//    Thread Utama:
//    Kotlin menggunakan Java Thread, sehingga pembuatan Thread di Kotlin sama seperti pembuatan Thread di Java
//    Untuk membuatThread Kita bisa menggunakan Interface Runnable Sebagai Kode Program yang akan dieksekusi,lalu menggunakan method Thread.start() untuk menalankan Thread tersebut
//    Ingat, Thread akan berjalan secara paralel, sehingga tidak akan ditunggu oleh thread utama
//    Kotlin memiliki helper function bernama thread() jika kita ingin membuatthread lebih singkat dan mudah

    @Test
    fun testMembuatThread(){
        val runable = Runnable {
            println(Date().toString())
            Thread.sleep(2_000)
            println("Hello Thread")
        }

        val thread = Thread(runable)
        thread.start()
        Thread.sleep(3_000)
        println(Date().toString())
    }

