//    Job:
//    Saat sebuah coroutine dijalankan menggunakan function launch, sebenernya function tersebut mengemablikan sebuah object job
//    dengan object job, kita bisa menjalankan, membatalkan atau menunggu sebuah coroutine selesai
//    Kita bisa mengatur kapan coroutine dijalankan dengan menambahkan parameter saat launch yakni CroutineStart
//    LAZY -> Akan menjalankan coroutine saat method start job dipanggil
//    DEFAULT -> akan langsung menjalankan coroutine secara default
    @Test
    fun testJob(){
        runBlocking{
            val j: Job = GlobalScope.launch(start = CoroutineStart.LAZY) {
                delay(2000)
                println("Coroutine Dones: ${Thread.currentThread().name}")
            }
            j.start() // -> Menjalankan Coroutine
            j.join() // -> Menunggu coroutine hingga selesai
//            j.cancel() -> Membatalkan coroutine berjalan
        }
    }

//    joinAll Function:
//    Kadang kita ingin membuat coroutine lebih dari satu sekaligus
//    untuk menunggu semua job coroutine selesai berjalan kita bisa menggunakan join() function
//    Namun jika kita panggil satu satu tiap job coroutine nya, akan sangat mengganggu sekali
//    Kotlin menyediakan joinAll(jobs) function untuk menunggu semua job selesai

    @Test
    fun testJoinAll(){
        runBlocking {
            val job1 = GlobalScope.launch {
                delay(1000)
                println("Job 1 Coroutine Dones: ${Thread.currentThread().name}")
            }

            val job2 = GlobalScope.launch {
                delay(2000)
                println("Job 2 Coroutine Dones: ${Thread.currentThread().name}")
            }

            joinAll(job1, job2)
        }
    }

//    Cancellable Coroutine
//    Sebelumnya kita sudah tahu bahwa job bisa kita batalkan menggunakan method cancel
//    membatalkan coroutine kadang diperlukan, misal ketika kode program di coroutine sudah terlalu lama
//    Semua function yang ada di package kotlinx.coroutines bisa dibatalkan
//    namun, jika dalam kode program kita,kita tdak mengecek status cancel, maka coroutine yang kita buat tidak akan bisa dibatalkan

    @Test
    fun testCanNotCancel(){
        runBlocking {
            val job = GlobalScope.launch {
                println("Start Coroutine ${Date()}")
                Thread.sleep(2000)
                println("End Coroutine ${Date()}")
            }

            job.cancel()
            delay(3000)
        }

    }

    //        Agar Coroutine bisa dibatalkan
//        Untuk mengecek apakah coroutine masih aktif atau tidak(selesai /dibatalkan), kita bisa menggunakan field isActive milik CoroutineScope
//        Untuk menandakan bahwa coroutine dibatalkan, kita bisa throw CancelatioException

    @Test
    fun testCanCancel(){
        runBlocking {
            val job = GlobalScope.launch {
                if (!isActive) throw CancellationException()
                println("Hello ${Date()}")
                ensureActive()
                Thread.sleep(2_000)
                ensureActive()
                // Ini tak akan tereksekusi
                println("World ${Date()}")
            }

            job.cancel()
            job.join()
        }
    }

//    Setelah Coroutine di Cancel
//    Standard coroutine adalah, ketika sebuah coroutine dibatalkan, maka kita perlu throw CancelableException
//    Karena throw CancellableException, artinya jika kita ingin melakukan sesuatu ketika asebuah coroutine dibatalkan, kita bisa menggunakan blok try catch finally

    @Test
    fun testCancelFinally(){
        runBlocking {
            val job = GlobalScope.launch {
                try {
                    println("Hello ${Date()}")
                    delay(2000)
                    println("World ${Date()}")
                } finally {
                    println("Selesai ${Date()}")
                }
            }

            job.cancelAndJoin()
        }
    }

//    Menggunakan Timeout
//    Kadang kita ingin sebuah coroutine berjalan tidak lebih dari waktu yang telah ditentukan
//    Sebenernya kita bisa melakukan hal tersebu secara manual, dengan cara menjalankan 2 job, dimana job ke dua akan membatalkan job pertama jika job pertama terlalu lama
//    Namun hal ini tidak perlu kita lakukan lagi, terdapat function withTimeout untuk melakukan hal tersebut
//    Jika terjadi timeout melebihi waktu yang telah kita tentukan, maka secara otomatis function with timeout akan throw TimeoutCancellationException
//    Misalkan kita ingin membuat kode tak lebih dari 5 detik
//    Kita bisa menggunakan fungsi withTimeout(durasi){coroutine fungsi}
    @Test
    fun testTimeout(){
        runBlocking {
            val job = GlobalScope.launch {
                withTimeout(Duration.ofMillis(5000)){
                    repeat(100) {
                        delay(1000)
                        println("$it ${Date()}")
                    }
                }
            }

            job.join()
        }
    }

//    Timeout Tanpa Membatalkan Coroutine
//    withTimeout akan throw TimeoutCancellationException, dimana itu adalah turunan dari CancelationException
//    Hal ini berakibat coroutine akan berhenti karena kita throw exception
//    Jika ada kasus dimana kita tidak ingin menghentikan coroutine nya, kita bisa menggunakan function withTimeoutOrNull, dimana ini tidak akan throw exception, hanya mengembalikan null ika terjadi timeout

    @Test
    fun testTimeoutOrNull(){
        runBlocking {
            val job = GlobalScope.launch {
                withTimeoutOrNull(Duration.ofMillis(5000)){
                    repeat(100) {
                        delay(1000)
                        println("$it ${Date()}")
                    }
                }
            }

            job.join()
        }
    }

//    Sequential Suspend Function
//    Suspend Function Tidak Async
//    secara default, sebenernya sebuah suspend function tidaklah async, saat kita mengakses beberapa suspend function, semua akan dieksekusi secara sequential
    suspend fun getH(): Int {
        delay(100)
        return 10
    }

    suspend fun getB(): Int {
        delay(200)
        return 20
    }

    @Test
    fun testSuspendFunction() {
        runBlocking {
            val start = System.currentTimeMillis()

            getB()
            getH()

            val total = System.currentTimeMillis() - start
            println("total waktu: $total ms")
        }
    }

//    Conccurent dengan launch
//    Jadi agar sebuah suspend funcion bisa berjalan secara conccurent, kita perlu menggunakan function launch ketika memanggil suspend function tersebit
//    Hal yang menyulitkan adalah, launch function mengembalikan Job dan di dalam Job, kita tidk bisa mengembalikan nilai hasil dari coroutine
//    Hal ini bisa dianalogikan bahwa launch itu alat menjalankan coroutine yang mengembalikan nilai Unit(Tidak bisa mengambalikan nilai)

    @Test
    fun testSuspendConccurent(){
        runBlocking {
            val start = System.currentTimeMillis()
            val job = GlobalScope.launch { getB() }
            val job1 = GlobalScope.launch { getH() }

            joinAll(job, job1)
            val total = System.currentTimeMillis() - start
            println("total waktu: $total ms")
        }
    }

//    Async Function
//    Untuk membuat coroutine, kita tidak hanya bisa menggunakan function launch, ada function async, yang bisa kita gunakan juga untuk membuat coroutine
//    Berbeda dengan launch dfunction yang mengembalikan Job, async function mengemablikan Deffered
//    Deffered adalah turunan dari Job, yang membedakan adalah, Deffered membawa value hasil dari async function
//    Deffered itu mirip konsep promise atau future, dimana datanya akan ada nanti di masa depan
//    Jika kita ingin menunggu data di Deffered sampai adam kita bisa menggunakan method await()

    @Test
    fun testSuspendAsync(){
        runBlocking {
            val start = System.currentTimeMillis()
            val b = GlobalScope.async { getB() }
            val f = GlobalScope.async { getH() }

            val w = b.await() + f.await()
            println("total nilai: $w")
            val total = System.currentTimeMillis() - start
            println("total waktu: $total ms")
        }
    }
//    awaitAll Function
//    Pada materi sebelumnya kita membuat beberapa async coroutine, lalu kita menggunakan await function menunggu hasilnya
//    Pada job, tersedia joinAll untuk menunggu semua launch coroutine selesai
//    Kotlin juga menyediakan awaitAll untuk menunggu semua Deffered selesai mengembalikan value
//    Await All merupakan generic function, dan mengembalikan List<T> data hasil dari semua Deffered nya

    @Test
    fun testAwaitAll(){
        runBlocking {
            val start = System.currentTimeMillis()
            val b = GlobalScope.async { getB() }
            val f = GlobalScope.async { getH() }

            val w = awaitAll(b, f).sum()
            println("total nilai: $w")
            val total = System.currentTimeMillis() - start
            println("total waktu: $total ms")
        }
    }

//    Coroutine Context
//    Coroutine selelu berjalan dibarengi dengan obect CoroutineContext
//    CoroutineContext adalah sebuah kumpulan data CoroutineContext.Element yang paling utama contohnya adalah Job (turunan dari CoroutineContext.Element) dan CoroutineDispatcher(yang akan dibahas di materi selanjutnya)

    @ExperimentalStdlibApi
    @Test
    fun testContext(){
        runBlocking{
            val job1 = GlobalScope.launch {
                println("ini konteks ${this.coroutineContext}")
            }
            val job = GlobalScope.launch {
                val context = coroutineContext
                println(context)
                println(context)
                println(context[Job])
                println(context[CoroutineDispatcher])
            }

            job.join()
            job1.join()
        }
    }

//    Coroutine Dispatcher
//    Selain ada Job di dalam CoroutineContext, ada juga object CoroutineDispatcher
//    CoroutineDispatcher digunakan untuk menentukan thread mana yang bertanggung jawab untuk mengeksekusi coroutine
//    Secara default, sudah ada di setting default dispatcher, namun kita bisa menggantinya jika kita mau

//    Dispatchers
//    Ada Object yang bisa kita gunakan untuk mengganti CoroutineDispatcher
//    Dispatcher.Default, ini adalah default dispatcher, isinya minimal 2 thread atau sebanyak jumlah cpu(mana yang lebih banyak), Dispatcher ini cocok untuk proses coroutine yang cpu bound
//    Dispatcher.IO, ini adalah dispatcher yang berisikan thread sesuai dengan kebetuhan, ketika butuh akan dibuat, ketika sudah tidak dibutuhkan, akan dihapus,mirip cache thread pool di executor service. Dispatcher ini akan sharing thread dengan Default Dispatcher
//    Dispatchers.Main, ini adalah dispatchers yang berisikan main thread UI, cocok ketika kita butuh running di thread main seperti Java Swing, JavaFX atau Android, Untuk menggunakan ini, kita harus menambahkan library ui tambahan

    @Test
    fun testDispatcher(){
        println("Unit test in thread ${Thread.currentThread().name} ")
        runBlocking {
            println("Unit test in thread ${Thread.currentThread().name} ")
            val job1 = GlobalScope.launch(Dispatchers.Default) {
                println("Job 1 ${Thread.currentThread().name}")
            }

            val job2 = GlobalScope.launch(Dispatchers.IO) {
                println("Job 1 ${Thread.currentThread().name}")
            }

            joinAll(job1, job2)
        }
    }

//    Unconfined vs Confined
//    Selain IO dan Main ada juga beberapa dispatcher yang lain
//    Dispatcher.Unconfined, ini adalah dispatcher yang tidak menunjuk thread apapun, biasanya akan melanjutkan thread di coroutine
//    Dispatcher.Confined, ini adalah dispatcher yang akan melanjutkan thread dari coroutine sebelumnya
//    Apa bedanya Unconfined dan Confined, pada UnConfined thread bisa berubah di tengah jalan jika memang terdapat code yang melakukan perubahan thread

    @Test
    fun testUnconfinedVSConfined(){
        runBlocking {
            val job = GlobalScope.launch(Dispatchers.Unconfined) {
                println("UnConfined : ${Thread.currentThread().name}")
                delay(1000)
                println("UnConfined : ${Thread.currentThread().name}")
            }

            val job1 = GlobalScope.launch {
                println("Confined : ${Thread.currentThread().name}")
                delay(2000)
                println("Confined : ${Thread.currentThread().name}")
            }

            job1.join()
            job.join()
        }
    }

//    Membuat Coroutine Dispatcher
//    Saat membuat aplikasi, kadang kita ingin flexible menentukan thread yang akan kita gunakan untuk menjalankan coroutine
//    Misal kita ingin membedakan thread untuk layer web, layer http, dan lain lain
//    Oleh karena ini, membuat coroutine dispatcher sendiri sangat direkomendasikan
//    Untuk membuat coroutine dispatcher secara manual, kita bisa melakukan nya dengan cara menggunakan ExecutorService
//    Kita bisa menggunakan method asCoroutineDispatcher

    @Test
    fun testCreateDispatcher(){
        val dispatcherService = Executors.newFixedThreadPool(4).asCoroutineDispatcher()
        val dispatcherWeb = Executors.newFixedThreadPool(4).asCoroutineDispatcher()

        runBlocking {
            val job1 = GlobalScope.launch(dispatcherService) {
                println("Service run in thread ${Thread.currentThread().name}")
            }

            val job2 = GlobalScope.launch(dispatcherWeb) {
                println("Service run in thread ${Thread.currentThread().name}")
            }
            joinAll(job1, job2)
        }
    }

//    withContext Function
//    Sebelumnya kita sudah tahu, bahwa ternyata kita melakukan delay(), suspend function tersebu akan di trigger di thread yang berbeda
//    Bagaiman caranya jika kita ingin menjalankan code program kita dalam coroutine di thread yang berbeda dengan thread coroutine awalnya
//    Untuk melakukan itu, kita bisa menggunakan function withContext()
//    Function withContext() sebenernya bisa kita gunakan untuk mengganti CoroutineContext, namun karena CoroutineDispatcher adalah turunan CoroutineContext, jadi kita bisa otomatis mengganti thread yang akan digunakan di coroutine menggunakan function withContext()

    @Test
    fun testWithContext() {
        val dispatcherClient = Executors.newFixedThreadPool(10).asCoroutineDispatcher()
        runBlocking {
            val job = GlobalScope.launch(Dispatchers.IO) {
                println("1. kode ini berjalan di ${Thread.currentThread().name}")
                withContext(dispatcherClient) {
                    println("2. kode ini berjalan di ${Thread.currentThread().name}")
                }
                println("3. kode ini berjalan di ${Thread.currentThread().name}")
            }
            job.join()
        }
    }

//    Non Cancellable Context

//    Masalah Check isActive di finally
//    Sebelumnya kita tahu bahwa setelah coroutine di cancel, dan jika kita ingin melakukan sesuatu kita bisa menggunakan block try-finally
//    Namun dalam block finally, kita tidak bisa menggunakan suspend method yang mengecek isActive, karena otomatis akan bernilai false dan otomatis batal

    @Test
    fun testCancelFinallySalah(){
        runBlocking{
            val job = GlobalScope.launch {
                try {
                    println("Hello ${Date()}")
                    delay(2000)
                    println("Hello ${Date()}")
                } finally {
                    println(isActive) // percuma karna akan selalu false
                    delay(1000)
                    println("Finish ${Date()}")
                }
            }

            job.cancelAndJoin()
        }
    }

//    Jika Kita butuh memanggil suspend function yang mengecek isActive di block finally, dan berharap tidak dibatalkan eksekusiya, maka kita bisa menggunakan NonCancellable
//    NonCancellable adalah coroutine context yang mengoverride nilai nilai cancellable sehingga seakan akan coroutine terseut tidak dibatalkan

    @Test
    fun testCancelFinllayBenar(){
        runBlocking{
            val job = GlobalScope.launch {
                try {
                    println("Hello ${Date()}")
                    delay(2000)
                    println("Hello ${Date()}")
                } finally {
                    withContext(NonCancellable){
                        println(isActive) // tidak akan batal karna sudah di wrap di noncancellable
                        delay(1000)
                        println("Finish ${Date()}")
                    }

                }
            }

            job.cancelAndJoin()
        }
    }

//    Coroutine Scope
//    Sampai test terakhir, kita selalu menggunakan GlobalScope untuk membuat coroutine, Kita belum membahas sama sekali soal Scope, seperti Apa itu GlobalScope?
//    GlobalScope sebenarnya adalah salah satu implementasi Coroutine Scope
//    Semua coroutine itu sebenarnya dijalankan dari sebuah coroutine scope
//    Function launch dan async yang selama ini kita gunakan, sebenarnya adalah extension function dari coroutine scope
//    Secara sederhana, coroutine scope adalah obejct life cycle nya coroutine

//    Penggunaan Coroutine Scope
//    CoroutineScope biasanya digunakan dalam sebuah flow yang saling berhubungan
//    Misal saat ktia membuka sebuah halaman di mobile, maka kita akan membuat screen, lalu mengambil data ke server, lalu setelah mendapatkannya. kita akan menampilkan data tersebut di screen
//    Flow tersebut harus saling terintegrasi, jika misal flow tersebut sukses maka harus sukses semua, jika dibatalkan maka harus dibatalkan proses selanjutnya
//    Hal tersebut jika diibaratkan tiap aktivitas adalah coroutine, maka flow tersebut di simpan di sebuah coroutine scope
//    Dan coroutine scope bisa dibatalkan nantinya dengan menggunakan method CoroutineScope.cancel()

//    GlobalScope
//    Sebelumnya kita selalu menggunakan GlobalScope untuk membuat coroutine
//    Sebenarnya penggunaan GlobalScope tidak dianjurkan dalam pembuatan aplikasi
//    Hal ini dikarenakan, jika semua coroutine menggunakan GlobalScope, maka secara otomatis akan sharing coroutine scope, hal ini agak menyulitkan saat kita misal ingin membatalkan sebuah flow,
//    karena saat sebuah coroutine scope dibatalkan, maka semua coroutine yang terdapat di scope tersebut akan dibatalakan

//    Membuat Coroutine Scope
    @Test
    internal fun testNewScope(){
        val scope = CoroutineScope(Dispatchers.Default)
    scope.launch {
        delay(2000)
        println("Run ${Thread.currentThread().name}: ${Date()}")
    }

    val scope2 = CoroutineScope(Dispatchers.IO)


    scope2.launch {
        delay(2000)
        println("Run ${Thread.currentThread().name}: ${Date()} Gak dibatalin")
    }

    scope.launch {
        delay(2000)
        println("Run ${Thread.currentThread().name}: ${Date()}")
    }

    runBlocking {

        //Jika ingin membatalkan suatu scope
        scope.cancel()
        println("Done")
    }
    }

//    CoroutineScope function
//    Kadang pembuatan coroutine scope itu terlalu kompleks jika hanya untuk kasus kasus yang sederhana, misal saja kita hanya ingin menggabungkan beberapa suspend function, lalu mengembalikan nilai tertentu
//    Pada kasus yang sederhana, kita bisa mennggunakan coroutine Scope functon untuk menggabungkan beberapa suspend function
//    Saat ada error di coroutine yang terdapat di dalam coroutine scope function tersebut, maka semua coroutine pun akan dibatalkan

    suspend fun getFoo(): Int {
        delay(1000)
        return 10
    }

    suspend fun getBar(): Int {
        delay(1000)
        return 20
    }

    suspend fun getSum(): Int = coroutineScope {
        val foo = async{getFoo()}
        val bar = async{getBar()}

        foo.await() + bar.await()
    }

    @Test
    fun testCoroutineScope(){
        val scope = CoroutineScope(Dispatchers.Default)
        val job = scope.launch {
           val res = getSum()
            println("Result $res")
        }

        runBlocking {
            job.join()
        }
    }

//    Coroutine Scope Parent & Child
//    Saat kita membuat sebuah coroutine dengan menggaunakan function coroutine Scope,
//    sebenernya kita telah membuat child scope dimana parent nya adalah scope yang diatasnya
//    Coroutine Scope itu saling berkaitan antara parent dan child nya
//    Saat kita membuat child scope, secaraotomatis child scope akan menggunakan dispatcher milik parent
//    Dan saat kita membatalkan parent scope, maka semua child scope nya pun akan dibatalkan

    @Test
    fun testChildDispatcher(){
        val parentDispatcher = Executors.newFixedThreadPool(10).asCoroutineDispatcher()
        val parentScope = CoroutineScope(parentDispatcher)
        val job = parentScope.launch {
            println("Parent thread is: ${Thread.currentThread().name}")
            coroutineScope {
                launch {
                    println("Child thread is : ${Thread.currentThread().name}")
                }
            }
        }

        runBlocking {
//            job.join()
            job.cancelAndJoin()
        }
    }

//    Coroutine Parent & Child
//    Selain Coroutine Scope, coroutine sendiri bisa memiliki child coroutine
//    Saat membuat coroutine child, secara otomatis kita akan mewarisi coroutine context yang ada di coroutine parent
//    Dan coroutine parent akan menunggu sampai eksekusi coroutine child nya selesai semua

    @Test
    fun testParentChildCoroutine(){
        runBlocking{
            val job = GlobalScope.launch {
                launch {
                    delay(2000)
                    println("Child 1 Done")
                }

                launch {
                    delay(3000)
                    println("Child 2 Done")
                }

                delay(1000)
                println("Parent Done")
            }

            job.join()
//            job.cancelAndJoin()
        }
    }

//    cancelChildren Function
//    Sebelumnya kita sudah bahas coroutine itu memiliki parent dan child
//    Coroutine akan direpresentasikan sebagai Job (Deferred turunan dari Job), dan di Job kita bisa mendapatkan semua children nya menggunakan filed children
//    Selain itu, ada sebuah function bernama cancelChildren, function ini bisa kita gunakan untuk membatalkan semua coroutine children
//    Jika kita membatalkan Job Parent, kita tidak perlu membatalkan children nya secara manual, karena saat Job dibatalkan, semua child nya akan otomatis dibatalkan juga

    @Test
    fun testCancelChildren(){
        runBlocking{
            val job = GlobalScope.launch {
                launch {
                    delay(3000)
                    println("Child 1 Done")
                }

                launch {
                    delay(3000)
                    println("Child 2 Done")
                }

                delay(1000)
                println("Parent Done")
            }

            delay(2000)
            job.cancelChildren()
            job.join()
        }
    }

//    Memberi Nama Coroutine
//    Selain dispatcher, salah satu corotine context yang lain adalah CoroutineName
//    CoroutineName bisa kita gunakan untuk mengubah nama coroutine sesuai dengan yang kita mau
//    Hal ini sangat bermanfaat ketika kita melakukan proses debugging

    @Test
    fun testRenameCoroutine(){
        val scope = CoroutineScope(Dispatchers.IO)
        val job = scope.launch(CoroutineName("kot1")) {
            println("in thread ${Thread.currentThread().name}")
            withContext(CoroutineName("anak_kot_1")){
                println("in thread ${Thread.currentThread().name}")
            }
        }

        runBlocking {
            job.join()
        }
    }

//    Menggabungkan Context Element
//    Seperti yang pernah dibahas di materi coroutine context
//    CoroutineContext adalah kumpulan dari elemen elemen, contoh turunannya, adalah job
//    CoroutineDispatcher dan yang terakhir yang sempat kita bahas adalah CoroutineName
//    CoroutineContext memiliki method plus, sehingga sebenarnya kita bisa menggabungkan beberapa context element secara sekaligus, misal Dispatcher dan CoroutineName misalnya

    @Test
    fun testCoroutineElementContextGabung(){
        val scope = CoroutineScope(Dispatchers.IO + CoroutineName("Dimas"))
        val job = scope.launch{
            println("${Thread.currentThread().name}")
        }

        runBlocking {
            job.join()
        }
    }

//    yield Function
//    Seperti yang pernah kita bahas sebelumnya, bahwa suspend function akan dijalankan secara sequential, artinya jika ada sebuah suspend function yang panjang dan lama, ada baiknya kita beri kesempatan ke suspend  functionn lain nya untuk dijalankan
//    Coroutine berjalan secara conccurent, artinya 1 dispacther bisa digunakan untuk mengeksekusi beberapa coroutine secara bergantian, Saat coroutine kita berjalan, dan jika kita ingin memberi kesempatan ke coroutine yang lain untuk berjalan, kita bisa menggunakan yield function
//    yield function itu bisa di cancel, artinya jika sebuah coroutine telah dibatalkan, maka secara otomatis yield function akan throw CancellationException

    suspend fun runNoYieldJob(number: Int) {
        println("Start job $number in thread ${Thread.currentThread().name}")
        println("End job $number in thread ${Thread.currentThread().name}")
    }

    suspend fun runYieldJob(number: Int) {
        println("Start job $number in thread ${Thread.currentThread().name}")
        yield()
        println("End job $number in thread ${Thread.currentThread().name}")
    }

    @Test
    fun testYieldFunction(){
        val dispatcher = Executors.newFixedThreadPool(10).asCoroutineDispatcher()
        val scope = CoroutineScope(dispatcher)

        runBlocking {
            scope.launch { runNoYieldJob(1) }
            scope.launch { runNoYieldJob(2) }

            scope.launch { runYieldJob(3) }
            scope.launch { runYieldJob(4) }

            delay(2000)
        }
    }

//    awaitCancellation Function
//    Secara default, sebuah coroutine akan berhenti ketika seluruh code selesai dijalankan
//    Jika ada kebutuhan kita tidak mau coroutine berhenti sampa di Job nya di cancel, maka kita bisa menggunakan function awaitCancellation
//    Function awaitCancellation akan throwCancellationException jika job di cancel, dan tidak akan mengentikan coroutine jika belum di cancel

    @Test
    fun testAwaitCancellation(){
        runBlocking {
            val job = launch {
                try {
                    println("Lakukan sesuatu")
                    awaitCancellation()
                } finally {
                    println("Coroutine cancelled")
                }
            }

            delay(5000)
            job.cancelAndJoin()
        }
    }

//    Exception Propagation
//    Secara garis besar, exception di coroutine itu ada yang di ekspose ke yang memanggil coroutine ada yang tidak
//    Pada launch, exception tidak akan di ekspose ketika memanggil function join, namun pada async exception akan di expose ketika memanggil di function di await

    @Test
    fun testExceptionAsync(){
        runBlocking {
            val deffered = GlobalScope.async<String> {
                println("launch coroutine")
                throw IllegalArgumentException()
            }
            try {
                deffered.await()
                println("finish async")
            }catch (err: IllegalArgumentException){
                println("Errnyanih: $err")
            }
            finally {
                println("finally async")
            }

        }
    }

//    Coroutine Exception Handler
//    Kadang kita ingin mengatur cara penangkapan exception di coroutine, hal ini bisa dilakukan dengan menggunakan interface CoroutineExceptionHandler
//    CoroutineExceptionHandler adalah turunan dari CoroutineContext.Element, sehingga kita bisa menambahkannya kedalam coroutine context
//    Ingat jenis CancellationException (dan turunannya) tidak akan diteruskan ke exception handler
//    Coroutine exception handler hanya jalan di launch, tidak jalan di async, untuk async, kita tetap harus menangkap excption nya secara manual

    @Test
    internal fun testExceptionHandler(){
        val exceptionHandler = CoroutineExceptionHandler{ context, throwable ->
            println("Ups, error dengan pesan ${throwable.message}")
        }

        val scope = CoroutineScope(Dispatchers.IO + exceptionHandler)

        runBlocking {
            val job = scope.launch(exceptionHandler) {
                println("run job")
                throw IllegalArgumentException("error")
            }
            try {
                job.join()
            } catch (err: IllegalArgumentException){
                println("ANJAY ADA ERRORNYA: $err")
            }

            println("finish")
        }
    }
}


